const ecommerceMaterials=['Cotton','Leather','Stainless Steel','Aluminum','Wood','Bamboo','Ceramic','Glass','Silicone','Polyester','Nylon','Recycled Plastic','Canvas','Rubber','Carbon Fiber'];
const ecommerceColors=['Black','White','Navy','Gray','Beige','Brown','Green','Blue','Red','Pink','Purple','Orange','Yellow','Silver','Gold','Cream','Olive','Charcoal','Teal','Natural'];
const ecommerceStyles=['Classic','Modern','Minimalist','Premium','Everyday','Lightweight','Heavy Duty','Compact','Professional','Essential'];
const ecommercePacks=['Single Pack','2-Pack','3-Pack','4-Pack','5-Pack','6-Pack','8-Pack','10-Pack','12-Pack','Bulk Pack'];
const ecommerceSizes=['XS','S','M','L','XL','XXL','Mini','Standard','Large','Extra Large'];
// 1000 x 15,000,000 addressable IDs. Labels are synthetic and may repeat; not verified products.
const ecommerceMax=15000000000;
function ecommerceRow(id){
 const z=((id-1)%ecommerceMax+ecommerceMax)%ecommerceMax;
 const cat=ecommerceGroups[Math.floor(z/15000000)];let variant=z%15000000;
 const material=ecommerceMaterials[variant%15];variant=Math.floor(variant/15);
 const color=ecommerceColors[variant%20];variant=Math.floor(variant/20);
 const style=ecommerceStyles[variant%10];variant=Math.floor(variant/10);
 const pack=ecommercePacks[variant%10];variant=Math.floor(variant/10);
 const size=ecommerceSizes[variant%10];
 // Materials and sizes are metadata, not forced into the product name when implausible.
 const productName=[style,color,cat.product].join(' ');
 return [z+1,cat.group,cat.category,productName,[material,size,pack].join(' / '),'Synthetic product concept'];
}
