const foodKeys=Object.keys(categories);const foodRadices=[25,4,10,10,10,20,20,20,30,20];const foodMax=480000000000;
function foodRow(id){let v=((id-1)%foodMax+foodMax)%foodMax,ix=[];for(const base of foodRadices){ix.push(v%base);v=Math.floor(v/base)}const [c,i,m,f,e,st,si,pr,sp,tx]=ix;const cat=foodKeys[c],ingredient=categories[cat][i],method=foodMethods[m],flavor=flavors[f],extra=extras[e],style=styles[st],side=sides[si],presentation=presentations[pr],spice=spices[sp],texture=textures[tx];return [id,cat,`${style} ${spice} ${method} ${ingredient} with ${flavor}, ${extra}; ${texture} finish; served as ${presentation} alongside ${side}`,ingredient,method,flavor,style,side,presentation]}
function foodId(offset){const sel=$('foodCategory').value;const category=sel==='all'?null:foodKeys.indexOf(sel);const base=((seed+offset-1)%foodMax+foodMax)%foodMax;return category===null?base+1:(Math.floor(base/25)*25+category+1)}

function row(type,i){let c=country(),nm;switch(type){
case 'jobs':{let ix=randomInt(sectors.length);return [i,c,sectors[ix],fields[ix],pick(roles)+' working in '+fields[ix]+' with '+pick(methods)+' methods'];}
case 'names':return [i,c,name()];
case 'emails':nm=name();return [i,c,nm,nm.toLowerCase().replaceAll(' ','.')+'.'+randomInt(1000000)+'@example.com'];
case 'passwords':{const alphabet='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*';let s='';for(let k=0;k<16;k++)s+=alphabet[randomInt(alphabet.length)];return [i,s];}
case 'languages':{let l=langFor(c),word=pick(l[2]);return [i,c,l[1],word[0],word[1]];}
case 'numbers':return [i,randomInt(1000000000)];
case 'ecommerce':return ecommerceRow(i);
case 'food':return foodRow(i);
case 'future':return window.ZhariefFutureHistory.row(i);
case 'books':return window.ZhariefBooks.row(i);
case 'music':return window.ZhariefMusic.row(i);case 'username':return window.ZhariefUsername.row(i,countries,$('countrySelect').value);case 'alien':return window.ZhariefAlienLanguage.row(i,$('alienLength').value);
case 'coding':{let items=dictionary50||window.ZHARIEF_CODE_DICTIONARY;let item=items[randomInt(items.length)];return [item.id||i,item.language,item.term,item.meaning,item.example];}
case 'domains':{const cons='bcdfghjklmnprstvz',vowels='aeiou',tlds=['com','net','org','io','ai','app','dev','tech','co','id','uk','de','jp','fr','shop','store','online','site','xyz','info','biz','me','us','ca','au','in','edu','cloud','studio','design'];let s='';for(let k=0;k<4;k++)s+=cons[randomInt(cons.length)]+vowels[randomInt(vowels.length)];let t=pick(tlds);return [i,s+'.'+t,'.'+t,s];}}}
