$('previewBtn').onclick=async()=>{try{count();if($('generatorType').value==='coding')await loadCodingDictionary();header();let body=$('preview').querySelector('tbody');body.replaceChildren();for(let i=0;i<Math.min(count(),10);i++){let tr=document.createElement('tr');for(let v of row($('generatorType').value,$('generatorType').value==='food'?foodId(i):seed+i)){let td=document.createElement('td');td.textContent=v;tr.appendChild(td)}body.appendChild(tr)}$('status').textContent='Showing up to 10 sample records. CSV export includes '+count().toLocaleString('en-US')+' new records.'}catch(e){$('status').textContent=e.message}};
