$('exportBtn').onclick=async()=>{if(busy)return;try{let n=count(),type=$('generatorType').value;if(type==='coding'){await loadCodingDictionary();if(n>dictionary50.length)throw Error('Coding Dictionary contains 50,000 unique entries. Choose 50,000 or fewer.');}busy=true;cancelled=false;$('exportBtn').disabled=true;$('cancelBtn').disabled=false;let chosen=null;if(type==='ecommerce')seed=randomInt(15000)*1000000+randomInt(1000000)+1;if(type==='alien')seed=Math.floor(Math.random()*window.ZhariefAlienLanguage.max)+1;if(type==='username')seed=Math.floor(Math.random()*window.ZhariefUsername.max)+1;if(type==='music')seed=Math.floor(Math.random()*window.ZhariefMusic.max)+1;if(type==='books')seed=Math.floor(Math.random()*window.ZhariefBooks.max)+1;if(type==='future')seed=Math.floor(Math.random()*window.ZhariefFutureHistory.max)+1;if(type==='food')seed=randomInt(480000)*1000000+randomInt(1000000)+1;if(type==='coding'){chosen=Array.from({length:dictionary50.length},(_,i)=>i);for(let i=chosen.length-1;i>0;i--){let j=randomInt(i+1);[chosen[i],chosen[j]]=[chosen[j],chosen[i]];}}let chunks=['\ufeff'+types[type].map(csv).join(',')+'\r\n'];for(let i=0;i<n;i+=500){if(cancelled){$('status').textContent='Export cancelled.';return}let lines=[];for(let j=i;j<Math.min(i+500,n);j++)lines.push((type==='coding'?(()=>{let x=dictionary50[chosen[j]];return [x.id,x.language,x.term,x.meaning,x.example]})():row(type,type==='food'?foodId(j):type==='ecommerce'?((seed+j-1)%ecommerceMax)+1:type==='music'?((seed+j-1)%window.ZhariefMusic.max)+1:type==='username'?((seed+j-1)%window.ZhariefUsername.max)+1:type==='alien'?((seed+j-1)%window.ZhariefAlienLanguage.max)+1:j+1)).map(csv).join(','));chunks.push(lines.join('\r\n')+'\r\n');$('status').textContent='Generating '+Math.min(i+500,n).toLocaleString()+' / '+n.toLocaleString()+' records…';await new Promise(r=>setTimeout(r,0))}let fileBlob=new Blob(chunks,{type:'text/csv;charset=utf-8'});if(type==='future'||type==='books'||type==='music'||type==='username'||type==='alien'){if(typeof CompressionStream==='undefined')throw Error('CSV.GZ requires a browser supporting CompressionStream (current Chrome, Firefox, or Edge).');fileBlob=await new Response(fileBlob.stream().pipeThrough(new CompressionStream('gzip'))).blob();}let url=URL.createObjectURL(fileBlob);let a=document.createElement('a');a.href=url;a.download='Zharief_'+type+'_'+n+(type==='future'||type==='books'||type==='music'||type==='username'||type==='alien'?'.csv.gz':'.csv');document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('status').textContent='Download ready: '+n.toLocaleString()+' records.'}catch(e){$('status').textContent=e.message}finally{busy=false;$('exportBtn').disabled=false;$('cancelBtn').disabled=true}};
